sys_script_client.script:
function onLoad() {

    // MSSCUSTODY-6227
    var switchAccount = g_form.getDisplayBox('bulk_id.amend_switch_account_ref');
    var securityID = g_form.getDisplayBox('bulk_id.amend_security_id_sec_id_ref');
    var counterpartyCode = g_form.getDisplayBox('bulk_id.amend_counterparty_code_ref');

    if (switchAccount) {
        switchAccount.addEventListener('keyup', function() {
                var errorElement = document.getElementById("security_id_error");
                g_form.addInfoMessage(errorElement);
                if (errorElement) {
                    errorElement.remove(); // Remove the element from the DOM
                } else {
                    //g_form.addErrorMessage("Error message element not found with id:", errorMessageId);
                }
            });
        }

        if (securityID) {
            securityID.addEventListener('keyup', function() {
                g_form.clearMessages();
            });
        }

        if (counterpartyCode) {
            counterpartyCode.addEventListener('keyup', function() {
                g_form.clearMessages();
            });
        }


    }
